-- Prompt 6 Supabase-ready schema documentation. Apply only after reviewing the production auth model.
create table if not exists public.learner_requirements (
  id uuid primary key default gen_random_uuid(), learner_id uuid not null references auth.users(id), subject text not null, topic text not null, level text not null, learning_goal text not null, description text not null, preferred_languages text[] not null default '{}', instructor_gender_preference text, class_format text not null, preferred_days text[] not null default '{}', preferred_start_time time, preferred_end_time time, timezone text not null, budget_min numeric, budget_max numeric, currency text, trial_preference text, visibility text not null default 'private' check (visibility in ('public','private')), status text not null default 'draft' check (status in ('draft','submitted','published','paused','responses_received','shortlisted','matched','closed','cancelled','under_review')), published_at timestamptz, expires_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index if not exists learner_requirements_public_idx on public.learner_requirements (visibility, status, subject, level, timezone);
create table if not exists public.requirement_responses (
  id uuid primary key default gen_random_uuid(), requirement_id uuid not null references public.learner_requirements(id) on delete cascade, instructor_id uuid not null references auth.users(id), message text not null, proposed_rate numeric, currency text, proposed_days text[] not null default '{}', proposed_start_time time, proposed_end_time time, timezone text not null, trial_proposal text, status text not null default 'draft' check (status in ('draft','submitted','viewed','shortlisted','accepted','declined','withdrawn','expired','under_review')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(requirement_id, instructor_id)
);
create table if not exists public.learner_shortlists (id uuid primary key default gen_random_uuid(), learner_id uuid not null references auth.users(id), requirement_id uuid not null references public.learner_requirements(id) on delete cascade, instructor_id uuid not null references auth.users(id), status text not null default 'shortlisted', created_at timestamptz not null default now(), unique(learner_id, requirement_id, instructor_id));
create table if not exists public.trial_requests (id uuid primary key default gen_random_uuid(), learner_id uuid not null references auth.users(id), instructor_id uuid not null references auth.users(id), requirement_id uuid references public.learner_requirements(id), course_id uuid, subject text not null, preferred_language text not null, requested_start_at timestamptz, requested_end_at timestamptz, timezone text not null, message text, status text not null default 'prepared' check (status in ('prepared','requested','accepted','declined','cancelled')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
-- RLS design: learners own requirements and their responses; instructors read only public published requirements and own responses; learners control shortlist/selection; trial requests require authenticated participants; no client receives contact documents or service-role keys.
-- Notification events: requirement_published, tutor_response_received, requirement_shortlisted, response_accepted, response_declined, trial_request_prepared, trial_request_status_changed. Delivery remains unconnected in demo mode.
